static inline float cd_max_silu(float x) {
    return x / (1.0f + expf(-x));
}

static inline float cd_max_read_w(
    const float* weights, int idx) {
#if defined(ESP32) || defined(ESP32S3)
    return pgm_read_float(&weights[idx]);
#else
    return weights[idx];
#endif
}

static inline void cd_max_dense_silu(
    const float* input,
    int in_dim,
    float* output,
    int out_dim,
    const float* weights,
    const float* bias) {
    for (int j = 0; j < out_dim; j++) {
        float sum = cd_max_read_w(bias, j);
        for (int i = 0; i < in_dim; i++) {
            sum += cd_max_read_w(weights, j * in_dim + i) * input[i];
        }
        output[j] = cd_max_silu(sum);
    }
}

static inline float cd_max_dense_linear(
    const float* input,
    int in_dim,
    const float* weights,
    const float* bias) {
    float sum = cd_max_read_w(bias, 0);
    for (int i = 0; i < in_dim; i++) {
        sum += cd_max_read_w(weights, i) * input[i];
    }
    return sum;
}

static inline float cd_max_predict(const float features[CD_MAX_N_FEATURES]) {
    float x[CD_MAX_N_FEATURES];
    for (int i = 0; i < CD_MAX_N_FEATURES; i++) {
        float rng = CD_MAX_FEATURE_MAXS[i] - CD_MAX_FEATURE_MINS[i];
        if (rng < 1e-9f) rng = 1.0f;
        x[i] = (features[i] - CD_MAX_FEATURE_MINS[i]) / rng;
    }

    float buf_a[CD_MAX_MAX_WIDTH];
    float buf_b[CD_MAX_MAX_WIDTH];
    const float* in_buf = x;
    int in_dim = CD_MAX_N_FEATURES;
    float* out_buf = buf_a;

    // Hidden layer 1: 5 -> 256
    cd_max_dense_silu(in_buf, in_dim, out_buf, CD_MAX_L1_OUT, CD_MAX_W1_W, CD_MAX_W1_B);
    in_buf = out_buf;
    in_dim = CD_MAX_L1_OUT;
    out_buf = (out_buf == buf_a) ? buf_b : buf_a;

    // Hidden layer 2: 256 -> 256
    cd_max_dense_silu(in_buf, in_dim, out_buf, CD_MAX_L2_OUT, CD_MAX_W2_W, CD_MAX_W2_B);
    in_buf = out_buf;
    in_dim = CD_MAX_L2_OUT;
    out_buf = (out_buf == buf_a) ? buf_b : buf_a;

    // Hidden layer 3: 256 -> 128
    cd_max_dense_silu(in_buf, in_dim, out_buf, CD_MAX_L3_OUT, CD_MAX_W3_W, CD_MAX_W3_B);
    in_buf = out_buf;
    in_dim = CD_MAX_L3_OUT;
    out_buf = (out_buf == buf_a) ? buf_b : buf_a;

    // Hidden layer 4: 128 -> 64
    cd_max_dense_silu(in_buf, in_dim, out_buf, CD_MAX_L4_OUT, CD_MAX_W4_W, CD_MAX_W4_B);
    in_buf = out_buf;
    in_dim = CD_MAX_L4_OUT;
    out_buf = (out_buf == buf_a) ? buf_b : buf_a;

    // Hidden layer 5: 64 -> 32
    cd_max_dense_silu(in_buf, in_dim, out_buf, CD_MAX_L5_OUT, CD_MAX_W5_W, CD_MAX_W5_B);
    in_buf = out_buf;
    in_dim = CD_MAX_L5_OUT;
    out_buf = (out_buf == buf_a) ? buf_b : buf_a;

    float out_norm = cd_max_dense_linear(in_buf, in_dim, CD_MAX_W6_W, CD_MAX_W6_B);
    return out_norm * CD_MAX_Y_STD + CD_MAX_Y_MEAN;
}

static inline float cd_max_drag_force(float cd, float rho, float velocity, float area) {
    return 0.5f * rho * velocity * velocity * cd * area;
}
